from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaField, SchemaObject


class NMSRespV1(SchemaObject):
    downlink_from_nms = SchemaField(name='downlink_from_nms', not_null=True)
    uplink_to_nms = SchemaField(name='uplink_to_nms', not_null=True)

    def __init__(self, downlink_from_nms, uplink_to_nms):
        self.downlink_from_nms = downlink_from_nms
        self.uplink_to_nms = uplink_to_nms

        super(NMSRespV1, self).__init__()
